#[test]
fn projections_match_original_c_checksum_across_resolutions_origins_and_zooms() {
    // Generated by including the original pstarmap.c in the isolated C oracle.
    let mut hash = 14695981039346656037u64;
    let mut mix = |v: i16| {
        hash = (hash ^ u64::from(v as u16)).wrapping_mul(1099511628211);
    };
    for (screen_width, screen_height) in [(320, 240), (640, 480), (400, 300)] {
        for (x, y) in [(4999, 4999), (0, 0), (9999, 9999), (438, 6372)] {
            for zoom in 0..=4 {
                let p = Projection {
                    origin: POINT { x, y },
                    zoom,
                    width: screen_width - 78,
                    height: screen_height - 13,
                };
                for v in (-40000..=40000).step_by(17) {
                    mix(p.x(v));
                    mix(p.y(v));
                }
                for v in -1000..=1000 {
                    mix(p.inverse_x(v));
                    mix(p.inverse_y(v));
                }
            }
        }
    }
    assert_eq!(hash, 8664724905253615563);
}

use super::*;

fn projection_at(zoom: i32, x: i16, y: i16) -> Projection {
    Projection {
        origin: POINT { x, y },
        zoom,
        width: 242,
        height: 227,
    }
}

#[test]
fn projection_rounds_signed_ties_away_from_zero() {
    assert_eq!(signed_div_with_error(5, 10), 1);
    assert_eq!(signed_div_with_error(-5, 10), -1);
    assert_eq!(signed_div_with_error(4, 10), 0);
    assert_eq!(signed_div_with_error(-4, 10), 0);
    let p = projection_at(0, 4999, 4999);
    assert_eq!((p.x(4999), p.y(4999)), (120, 113));
    assert_eq!((p.x(0), p.x(9999)), (0, 241));
    assert_eq!((p.y(0), p.y(9999)), (226, 0));
    assert_eq!((p.inverse_x(120), p.inverse_y(113)), (4999, 4999));
}

#[test]
fn inverse_shifts_negative_products_before_truncating_division() {
    let p = projection_at(4, 4999, 4999);
    assert_eq!(p.inverse_x(119), 4997);
    assert_eq!(p.inverse_x(121), 5001);
    assert_eq!(p.inverse_y(112), 5001);
    assert_eq!(p.inverse_y(114), 4997);
    for zoom in 0..=4 {
        let p = projection_at(zoom, 1234, 5678);
        assert_eq!((p.x(1234), p.y(5678)), (120, 113));
        assert_eq!((p.inverse_x(120), p.inverse_y(113)), (1234, 5678));
    }
}

#[test]
fn projection_uses_live_screen_dimensions() {
    let p = Projection {
        origin: POINT { x: 4999, y: 4999 },
        zoom: 0,
        width: 562,
        height: 467,
    };
    assert_eq!((p.x(4999), p.y(4999)), (280, 233));
    assert_eq!((p.inverse_x(280), p.inverse_y(233)), (4999, 4999));
    assert_eq!(p.x(9999), 561);
}

#[test]
fn autopilot_dashes_keep_c_postdecrement_phase() {
    let mut p = POINT { x: 0, y: 0 };
    let mut walk = LineWalk::new(7, 3);
    walk.delta &= !1;
    let mut points = Vec::new();
    loop {
        let before = walk.delta;
        walk.delta -= 1;
        if before == 0 {
            break;
        }
        if walk.delta & 1 == 0 {
            points.push((p.x, p.y));
        }
        walk.step(&mut p);
    }
    assert_eq!(points, [(1, 0), (3, 1), (5, 2)]);
}

#[test]
fn animation_line_walker_includes_c_extra_final_step() {
    for (dx, dy) in [(4, 2), (-4, 2), (4, -2), (-4, -2), (0, 4), (4, 0)] {
        let mut p = POINT { x: 100, y: 100 };
        let mut walk = LineWalk::new(dx, dy);
        let mut steps = 0;
        loop {
            walk.step(&mut p);
            steps += 1;
            let before = walk.delta;
            walk.delta -= 1;
            if before == 0 {
                break;
            }
        }
        assert_eq!(steps, 5);
        // UpdateMap overwrites this animated location with the actual location
        // after the loop, including the original extra final iteration.
        assert_eq!((p.x, p.y), (100 + dx + dx.signum(), 100 + dy + dy.signum()));
    }
}

#[test]
fn fuel_adds_half_a_tenth_only_outside_quasispace() {
    let origin = POINT { x: 0, y: 0 };
    let destination = POINT { x: 300, y: 400 };
    assert_eq!(
        fuel_requirement(origin, destination, 0, |f| {
            assert_eq!(f, 250000);
            500
        }),
        505
    );
    assert_eq!(fuel_requirement(origin, destination, 1, |_| 500), 505);
    assert_eq!(
        fuel_requirement(origin, destination, 2, |_| panic!(
            "quasispace must not compute a root"
        )),
        0
    );
    assert_eq!(
        fuel_requirement(origin, origin, 0, |_| panic!(
            "same location must not compute a root"
        )),
        0
    );
}

#[test]
fn repair_union_clips_and_aligns_scanlines_after_label_padding() {
    let last = RECT {
        corner: POINT { x: -5, y: -3 },
        extent: EXTENT {
            width: 20,
            height: 20,
        },
    };
    let next = RECT {
        corner: POINT { x: 230, y: 219 },
        extent: EXTENT {
            width: 30,
            height: 30,
        },
    };
    let r = repair_rectangle(last, next, 242, 227);
    assert_eq!(
        (r.corner.x, r.corner.y, r.extent.width, r.extent.height),
        (0, 0, 242, 227)
    );
    let r = repair_rectangle(
        zero_rect(),
        RECT {
            corner: POINT { x: 100, y: 100 },
            extent: EXTENT {
                width: 20,
                height: 20,
            },
        },
        242,
        227,
    );
    assert_eq!(
        (r.corner.x, r.corner.y, r.extent.width, r.extent.height),
        (0, 0, 135, 120)
    );
}

#[test]
fn rectangle_intersection_excludes_touching_edges() {
    let a = RECT {
        corner: POINT { x: 10, y: 10 },
        extent: EXTENT {
            width: 20,
            height: 20,
        },
    };
    let mut b = a;
    b.corner.x = 30;
    assert!(!intersects(a, b));
    b.corner.x = 29;
    assert!(intersects(a, b));
}

#[test]
fn rgb15_ignores_legacy_palette_indices_and_keeps_opaque_alpha() {
    let c = rgb15(3, 11, 31);
    assert_eq!((c.r, c.g, c.b, c.a), (24, 90, 255, 255));
    assert_eq!(RACE_COLORS.len(), 23);
    assert_eq!(
        (ARILOU_HOME.x, ARILOU_HOME.y),
        (5000 + (((63 * 12) >> 1) * 3), 5000 + (((50 * 12) >> 1) * 3))
    );
}
